/* Shared packet bounds for live and original-pose diagnostic consumers. */
static uint16_t endpoint_bounds[128][4],endpoint_model_bounds[16][4];static uint32_t endpoint_kinds[128];static unsigned endpoint_bounded_models;
static void endpoint_select(const NFScenePacket*p){double alpha;const uint8_t*b;uint32_t count;memcpy(&count,p->section[1].data+4,4);if(!nf_scene_packet_bounds(p,&alpha,&b)||!isfinite(alpha)||alpha<0||alpha>1||count>128)exit(34);for(unsigned i=0;i<count;i++){memcpy(endpoint_bounds[i],b+i*8,8);memcpy(endpoint_kinds+i,p->section[4].data+8+i*20,4);}endpoint_bounded_models=0;if(nf_scene_packet_model_bounds(p,&b)){endpoint_bounded_models=nf_scene_packet_model_count(p);memcpy(endpoint_model_bounds,b,endpoint_bounded_models*8);}}
static void endpoint_model_clip(int model){if(model<0||(unsigned)model>=endpoint_bounded_models){glDisable(GL_SCISSOR_TEST);return;}const uint16_t*b=endpoint_model_bounds[model];int x0=(int)ceil(300+b[0]*13.5-.5),x1=(int)ceil(300+b[1]*13.5-.5),y0=(int)ceil((160-b[3])*13.5-.5),y1=(int)ceil((160-b[2])*13.5-.5);glEnable(GL_SCISSOR_TEST);glScissor(x0,y0,x1>x0?x1-x0:0,y1>y0?y1-y0:0);}
static void endpoint_clip(int ring){if(ring<0){glDisable(GL_SCISSOR_TEST);return;}if(endpoint_kinds[ring]!=2)return;const uint16_t*b=endpoint_bounds[ring];/* Original walls clip inclusive halfword columns and retain terminal rows. Expand only the portal support, never quantize continuous geometry. */unsigned left=(b[0]/2)*2,right=(b[1]/2)*2+2,bottom=b[3]+2;if(right>240)right=240;if(bottom>160)bottom=160;int x0=(int)ceil(300+left*13.5-.5),x1=(int)ceil(300+right*13.5-.5),y0=(int)ceil((160-bottom)*13.5-.5),y1=(int)ceil((160-b[2])*13.5-.5);glEnable(GL_SCISSOR_TEST);glScissor(x0,y0,x1>x0?x1-x0:0,y1>y0?y1-y0:0);}
static int endpoint_road(unsigned ring,double*l,double*r,double*t,double*b){if(ring>=128||endpoint_kinds[ring]!=1)return 0;*l=endpoint_bounds[ring][0];*r=endpoint_bounds[ring][1];*t=endpoint_bounds[ring][2];*b=endpoint_bounds[ring][3];return 1;}
